class Widget {
  config: any;
  constructor(config: any) { this.config = config; }
  clone() { return Object.assign(Object.create(Object.getPrototypeOf(this)), this); }
}

const registry: Record<string, Widget> = {
  blue: new Widget({color: 'blue'}),
  red: new Widget({color: 'red'})
};

const newWidget = registry['blue'].clone();

class Order {
  items: any[];
  metadata: any;
  constructor(items: any[], metadata: any) { this.items = items; this.metadata = metadata; }
  clone() { return Object.assign(Object.create(Object.getPrototypeOf(this)), this); }
}

const sample = new Order([{id:1}], {user: 'alice'});
const o2 = sample.clone();

